INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Verwende ich 2^n, um die Anzahl der Subnetze zu bestimmen?', 2, '[{"text": "Ja", "correct": true, "because": "n steht für geliehene Bits"}, {"text": "Nein", "correct": false, "because": "Standardformel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen mit 4 geliehenen Bits?', 3, '[{"text": "16", "correct": true, "because": "2^4 = 16"}, {"text": "8", "correct": false, "because": "Für 3 Bits"}, {"text": "32", "correct": false, "because": "Für 5 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) 2 geliehene Bits ergeben 4 Subnetze. b) n kann 0 sein.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^2 = 4, b) 2^0 = 1"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Berechnung der Subnetzanzahl irrelevant?', 4, '[{"text": "Geliehene Bits", "correct": false, "because": "Kern der Formel"}, {"text": "Exponentiation", "correct": false, "because": "2^n ist die Basis"}, {"text": "Netzwerkgeschwindigkeit", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 3 geliehene Bits 8 Subnetze ergeben?', 2, '[{"text": "Ja", "correct": true, "because": "2^3 = 8"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen bei /24, wenn ich auf /28 gehe?', 3, '[{"text": "16", "correct": true, "because": "28-24 = 4 Bits, 2^4 = 16"}, {"text": "8", "correct": false, "because": "Für 3 Bits"}, {"text": "4", "correct": false, "because": "Für 2 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die Subnetzanzahl entscheidend?', 5, '[{"text": "Anzahl geliehener Bits", "correct": true, "because": "Definiert n"}, {"text": "Formel 2^n", "correct": true, "because": "Berechnet Subnetze"}, {"text": "Hostanzahl", "correct": false, "because": "Separat berechnet"}, {"text": "Gateway-Adresse", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 5 geliehene Bits sind 32 Subnetze. b) n hängt von der Hardware ab. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^5 = 32, b) von Maske"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was benötige ich nicht, um die Subnetzanzahl zu berechnen?', 4, '[{"text": "Netzwerkmaske", "correct": false, "because": "Bestimmt geliehene Bits"}, {"text": "Exponentiation", "correct": false, "because": "Teil der Formel"}, {"text": "Protokollversion", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ergeben 2 geliehene Bits bei /16 genau 4 Subnetze?', 2, '[{"text": "Ja", "correct": true, "because": "2^2 = 4"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze gibt es bei /20 mit /23?', 4, '[{"text": "8", "correct": true, "because": "23-20 = 3 Bits, 2^3 = 8"}, {"text": "4", "correct": false, "because": "Für 2 Bits"}, {"text": "16", "correct": false, "because": "Für 4 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 1 geliehenes Bit keine Subnetze erzeugt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "2^1 = 2 Subnetze"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Subnetzaufteilung entscheidend?', 3, '[{"text": "Anzahl geliehener Bits", "correct": true, "because": "Bestimmt 2^n"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufallsfaktor", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /24 zu /26 ergibt 4 Subnetze. b) n ist immer größer als 8.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "26-24 = 2, 2^2 = 4, n variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte beeinflussen die Subnetzanzahl?', 5, '[{"text": "Geliehene Bits", "correct": true, "because": "Definiert n"}, {"text": "Exponent 2", "correct": true, "because": "Formelbasis"}, {"text": "Netzwerkadresse", "correct": false, "because": "Nur Bereich"}, {"text": "Broadcastadresse", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was spielt bei der Subnetzanzahl keine Rolle?', 3, '[{"text": "Bitanzahl", "correct": false, "because": "Bestimmt n"}, {"text": "Formel 2^n", "correct": false, "because": "Kern der Berechnung"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind 6 geliehene Bits gleich 64 Subnetze?', 3, '[{"text": "Ja", "correct": true, "because": "2^6 = 64"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /27 aus /24 8 Subnetze macht?', 2, '[{"text": "Ja", "correct": true, "because": "27-24 = 3, 2^3 = 8"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen bei /16 mit 5 geliehenen Bits?', 4, '[{"text": "32", "correct": true, "because": "2^5 = 32"}, {"text": "16", "correct": false, "because": "Für 4 Bits"}, {"text": "64", "correct": false, "because": "Für 6 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formel passt zur Subnetzanzahl?', 3, '[{"text": "2^n", "correct": true, "because": "n = geliehene Bits"}, {"text": "2^(32-n)", "correct": false, "because": "Für Hosts"}, {"text": "n + 2", "correct": false, "because": "Falsche Formel"}]');
